function draw(ctx, state, t) {
  var top = 36;
  var bot = 286;
  var S = 1200;
  var step = state.step;
  var vhat = state.vhat;
  var beta2 = state.beta2;
  var eps = state.eps;
  function fmt(v) { return Math.round(v * 100) / 100; }
  var denom = Math.sqrt(vhat) + eps * 5000;
  var eff = step * (0.5 + (beta2 - 0.9) * 5);
  var y = eff / denom * S;
  var ythr = bot - 0.1 * S;
  var x = 48;
  var yv = 0;
  var dx = 0;
  var clipped = false;
  var mid = 304;
  var xb = 0;
  var yb = 0;
  var r = 0;
  ctx.clearRect(0, 0, state.w, state.h);
  ctx.fillStyle = "#f6f3ec";
  ctx.fillRect(0, 0, state.w, state.h);
  ctx.strokeStyle = "#1f4b99";
  ctx.lineWidth = 2;
  ctx.beginPath();
  for (x = 48; x <= 560; x = x + 8) {
    dx = (x - mid) / 100;
    yv = 140 + dx * dx * vhat * 10;
    if (yv > bot) { yv = bot; clipped = true; }
    if (yv < top) { yv = top; clipped = true; }
    if (x === 48) { ctx.moveTo(x, yv); } else { ctx.lineTo(x, yv); }
  }
  ctx.stroke();
  if (clipped === true) { ctx.fillStyle = "#1f4b99"; ctx.fillText("clipped", 500, top + 16); }
  ctx.strokeStyle = "#c4512c";
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(48, ythr);
  ctx.lineTo(560, ythr);
  ctx.stroke();
  ctx.strokeStyle = "#1f4b99";
  ctx.lineWidth = 3;
  ctx.beginPath();
  if (y > bot - top) {
    ctx.moveTo(48, bot);
    ctx.lineTo(560, top);
    ctx.stroke();
    ctx.fillStyle = "#1f4b99";
    ctx.fillText("clipped", 500, top + 32);
  } else {
    ctx.moveTo(48, bot - y);
    ctx.lineTo(560, bot - y);
    ctx.stroke();
  }
  xb = mid + (0.999 - beta2) * 2000;
  if (xb > 560) { xb = 560; }
  if (xb < 48) { xb = 48; }
  dx = (xb - mid) / 100;
  yb = 140 + dx * dx * vhat * 10;
  if (yb > bot) { yb = bot; }
  r = 6 + eps * 2000;
  ctx.fillStyle = "#c4512c";
  ctx.beginPath();
  ctx.arc(xb, yb, r, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = "#1f4b99";
  ctx.font = "12px sans-serif";
  ctx.fillText("threshold " + fmt(0.1), 48, ythr - 8);
  ctx.fillText("step = " + fmt(y / S), 48, 318);
  ctx.fillText("toy 1412.6980 bias on", 48, 344);
}
